local function zone(side,prefix,pts) local z={} for i,p in ipairs(pts) do local n=prefix..'-'..i; must(ScenEdit_AddReferencePoint({side=side,name=n,latitude=p[1],longitude=p[2]}),'rp '..n); z[#z+1]=n end return z end
local function patrol(side,name,subtype,pts,onstation,active) local m=must(ScenEdit_AddMission(side,name,'Patrol',{type=subtype,zone=zone(side,name,pts)}),'mission '..name); ScenEdit_SetMission(side,m.guid,{isactive=active,OneThirdRule=true,OnStation=onstation,CheckOPA=true,CheckWWR=true}); return m.guid end
local function support(side,name,pts,onstation) local m=must(ScenEdit_AddMission(side,name,'Support',{zone=zone(side,name,pts)}),'mission '..name); ScenEdit_SetMission(side,m.guid,{isactive=true,OneThirdRule=true,OnStation=onstation,LoopType=1}); return m.guid end
local function assign(ids,m) for _,id in ipairs(ids) do if U[id] then ScenEdit_AssignUnitToMission(U[id],m) end end end
